"""Summarize ablation learning curves generated by NetCC-RL."""

import argparse
from collections import Counter
import csv
from itertools import product
import json
import math
from pathlib import Path
from netcc_rl.compat.ablation import normalize_record
from statistics import mean, stdev

from netcc_rl.matrix import ALL_ARMS, MATRIX

BUDGET = 1_000_000
EVAL_STEPS = list(range(0, BUDGET + 1, 50_000))
METRICS = ("final_eval_mean", "late5_mean", "eval_auc_normalized")


def write_csv(path, rows):
    with path.open("x", newline="", encoding="utf-8") as stream:
        if rows:
            writer = csv.DictWriter(stream, fieldnames=list(rows[0]), lineterminator="\n")
            writer.writeheader()
            writer.writerows(rows)


def late_stats(points, count):
    steps = EVAL_STEPS[-count:]
    counts = Counter(step for step, _ in points)
    if any(counts[step] != 1 for step in steps):
        return None, None
    values = dict(points)
    tail = [values[step] for step in steps]
    return mean(tail), stdev(tail)


def normalized_auc(points):
    if len(points) < 2 or any(a[0] >= b[0] for a, b in zip(points, points[1:])):
        return None
    total = math.fsum((b_step - a_step) * (a + b) / 2
                      for (a_step, a), (b_step, b) in zip(points, points[1:]))
    return total / (points[-1][0] - points[0][0])


def analyze(path, environment, arm):
    result = dict(environment=environment, arm=arm, **ALL_ARMS[arm], status="pending",
                  final_eval_mean=None, late3_mean=None, late3_sd=None, late5_mean=None,
                  late5_sd=None, eval_auc_normalized=None)
    if not path.is_file():
        return result, [], []
    rows = [normalize_record(json.loads(line)) for line in path.read_text().splitlines()]
    evaluations = [row for row in rows if row["kind"] == "eval"]
    if any((row["ablation_environment"], row["ablation_arm"], row["training_seed"]) != (environment, arm, 0)
           or row["eval_policy"] != "stochastic" or row["eval_seed"] != 202600
           or len(row["episodes"]) != 20 for row in evaluations):
        raise ValueError(f"Unexpected evaluation protocol in {path}")
    points = [(row["step"], row["episode_return"]) for row in evaluations]
    if not all(math.isfinite(value) for _, value in points):
        raise FloatingPointError(f"Nonfinite evaluation in {path}")
    if [step for step, _ in points] != EVAL_STEPS:
        return result, points, []
    result.update(status="complete", final_eval_mean=points[-1][1],
                  eval_auc_normalized=normalized_auc(points))
    result["late3_mean"], result["late3_sd"] = late_stats(points, 3)
    result["late5_mean"], result["late5_sd"] = late_stats(points, 5)
    return result, points, evaluations[-1]["episodes"]


def effects(rows, environment):
    historical = [r for r in rows if r["environment"] == environment and r["arm"] in MATRIX["arms"]]
    for metric, factor in product(METRICS, ("G", "D", "A")):
        groups = [[row[metric] for row in historical if row[factor] == f"{factor}{level}"]
                  for level in (0, 1)]
        means = [mean(values) if len(values) == 4 and None not in values else None for values in groups]
        yield dict(environment=environment, metric=metric, factor=factor,
                   level0_mean=means[0], level1_mean=means[1],
                   level1_minus_level0=means[1]-means[0] if None not in means else None)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-root", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--set", choices=("historical", "all"), default="all")
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=False)
    arms = MATRIX["arms"] if args.set == "historical" else ALL_ARMS
    rows, raw, episode_rows = [], [], []
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    for env in MATRIX["environments"]:
        fig, ax = plt.subplots(figsize=(8, 4))
        plotted = False
        for arm in arms:
            path = args.run_root / f"{env}-{arm}-seed0" / "metrics.jsonl"
            row, points, episodes = analyze(path, env, arm)
            rows.append(row)
            raw.extend(dict(environment=env, arm=arm, step=step, value=val) for step, val in points)
            episode_rows.extend(dict(environment=env, arm=arm, seed=ep["seed"], value=ep["return"])
                                for ep in episodes)
            if points:
                ax.plot(*zip(*points), label=arm)
                plotted = True
        if plotted:
            ax.set(xlabel="Real transitions", ylabel="Mean return", title=env.title())
            ax.legend(ncols=3)
            fig.tight_layout()
            fig.savefig(args.output / f"{env}.png", dpi=155)
        plt.close(fig)
    write_csv(args.output / "results_by_run.csv", rows)
    write_csv(args.output / "factor_effects.csv",
              [row for env in MATRIX["environments"] for row in effects(rows, env)])
    write_csv(args.output / "raw_eval_points.csv", raw)
    write_csv(args.output / "final_evaluation_episodes.csv", episode_rows)


if __name__ == "__main__":
    main()
